     1→import Phaser from 'phaser';
     2→import { gachaPull, type PulledCharacter } from '../utils/gacha';
     3→import { CHARACTERS, getCharacterDef, addOwnedCharacter, type CharacterDef } from '../utils/character';
     4→import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';
     5→
     6→// vids/ 디렉토리에 개인 영상이 존재하는 캐릭터 목록
     7→const CHARS_WITH_VIDS = new Set([
     8→  'chibi', 'hacker', 'miner', 'maehwa', 'archieve', 'glitch', 'noise', 'sentinel', 'legacy',
     9→]);
    10→
    11→const GRADE_COLORS: Record<string, number> = {
    12→  UR: 0xffaa00,
    13→  SR: 0x4488ff,
    14→  R:  0x44bb44,
    15→  N:  0xaaaaaa,
    16→  '등급외': 0xcccccc,
    17→};
    18→
    19→// 현재 픽업 배너 설정 — 출시 캐릭터 변경 시 characterId만 수정
    20→const CURRENT_BANNER = {
    21→  characterId: 'legacy',
    22→  label: '신규 출시',
    23→};
    24→
    25→export default class GachaScene extends Phaser.Scene {
    26→  private skorBalance = 0;
    27→  private remainingSkor = 0;
    28→  private pullResults: PulledCharacter[] = [];
    29→  private revealIndex = 0;
    30→  private terminalTexts: Phaser.GameObjects.Text[] = [];
    31→  private skipTerminal = false;
    32→
    33→  constructor() {
    34→    super('GachaScene');
    35→  }
    36→
    37→  preload() {
    38→    // 공통 연출 영상
    39→    if (!this.cache.video.exists('gacha')) {
    40→      this.load.video('gacha', 'assets/vids/gacha.mp4');
    41→    }
    42→    // 캐릭터 픽셀 이미지 (작은 webp, 전부 사전 로드)
    43→    for (const c of CHARACTERS) {
    44→      if (!this.textures.exists(c.imageKey)) {
    45→        this.load.image(c.imageKey, c.imagePath);
    46→      }
    47→    }
    48→    // 픽업 배너 캐릭터 일러스트
    49→    const bannerDef = CHARACTERS.find(c => c.id === CURRENT_BANNER.characterId);
    50→    if (bannerDef && !this.textures.exists(bannerDef.illustKey)) {
    51→      this.load.image(bannerDef.illustKey, bannerDef.illustPath);
    52→    }
    53→    // 리빌 화면 공통 배경
    54→    if (!this.textures.exists('gacha_background')) {
    55→      this.load.image('gacha_background', 'assets/backgrounds/gacha_background.webp');
    56→    }
    57→  }
    58→
    59→  create() {
    60→    this.pullResults = [];
    61→    this.revealIndex = 0;
    62→    this.buildLobby();
    63→  }
    64→
    65→  // ═══════════════════════════════════════════════════
    66→  // LOBBY
    67→  // ═══════════════════════════════════════════════════
    68→
    69→  private async buildLobby() {
    70→    this.clearUI();
    71→
    72→    const bannerDef = getCharacterDef(CURRENT_BANNER.characterId);
    73→    const gradeColorInt = parseInt(bannerDef.gradeColor.replace('#', ''), 16);
    74→
    75→    // ── 일러스트 배경 ──
    76→    const illust = this.add.image(200, 300, bannerDef.illustKey);
    77→    illust.setDisplaySize(400, 600);
    78→
    79→    // ── 하단 버튼 영역 그라데이션 (바닥에서 올라오는 어둠) ──
    80→    const gradSteps = 14;
    81→    for (let i = 0; i < gradSteps; i++) {
    82→      this.add.rectangle(200, 600 - i * 22, 400, 22, 0x000000, (gradSteps - i) * 0.052);
    83→    }
    84→
    85→    // ── 상단: 배너 배지 ──
    86→    this.add.rectangle(200, 36, 140, 30, 0x000000, 0.75)
    87→      .setStrokeStyle(1.5, gradeColorInt);
    88→    this.add.text(200, 36, `✦  ${CURRENT_BANNER.label}  ✦`, {
    89→      fontSize: '13px', color: bannerDef.gradeColor, fontStyle: 'bold',
    90→      stroke: '#000000', strokeThickness: 3,
    91→    }).setOrigin(0.5);
    92→
    93→    // ── 캐릭터 등급 + 이름 ──
    94→    this.add.text(200, 220, bannerDef.grade, {
    95→      fontSize: '14px', color: bannerDef.gradeColor, fontStyle: 'bold',
    96→      letterSpacing: 6, stroke: '#000000', strokeThickness: 6,
    97→    }).setOrigin(0.5);
    98→
    99→    this.add.text(200, 258, bannerDef.name, {
   100→      fontSize: '46px', color: '#ffffff', fontStyle: 'bold',
   101→      stroke: '#000000', strokeThickness: 10,
   102→    }).setOrigin(0.5);
   103→
   104→    // ── SKOR 잔액 — 캐시는 표시용만, 실제 잔액은 서버 응답 전까지 -1 ──
   105→    const cached = getCachedSkorBalance();
   106→    const initialText = cached !== null ? `💰  ${cached} SKOR` : '💰  -- SKOR';
   107→    const skorText = this.add.text(200, 408, initialText, {
   108→      fontSize: '15px', color: '#aaaaaa',
   109→      stroke: '#000000', strokeThickness: 4,
   110→    }).setOrigin(0.5);
   111→    this.skorBalance = -1; // 서버 확인 전까지 뽑기 불가
   112→
   113→    // ── 뽑기 버튼 ──
   114→    this.buildPullButtons(true);
   115→
   116→    // 서버에서 최신 잔액 가져와 갱신
   117→    this.skorBalance = await getSkorBalance();
   118→    if (!this.scene.isActive()) return;
   119→    cacheSkorBalance(this.skorBalance);
   120→    skorText.setText(`💰  ${Math.floor(this.skorBalance)} SKOR`);
   121→  }
   122→
   123→  private drawTerminalChrome(isUR = false) {
   124→    const borderColor = isUR ? 0xff3333 : 0x00ff41;
   125→    const textColor   = isUR ? '#ff3333' : '#00ff41';
   126→    const titleColor  = isUR ? '#cc0000' : '#00cc33';
   127→    const title       = isUR ? 'root@krypt — [EMERGENCY OVERRIDE]' : 'root@krypt — entity_summon';
   128→
   129→    this.add.rectangle(200, 342, 370, 172, 0x000000)
   130→      .setStrokeStyle(1, borderColor, 0.8);
   131→    this.add.text(26, 260, '● ● ●', { fontSize: '11px', color: textColor });
   132→    this.add.text(200, 261, title, {
   133→      fontSize: '11px', color: titleColor, fontFamily: 'monospace',
   134→    }).setOrigin(0.5);
   135→  }
   136→
   137→  private buildPullButtons(_fromLobby = false) {
   138→    this.addPullButton(200, 448, '1회 소환', '100 SKOR', 'single');
   139→    this.addPullButton(200, 516, '10회 소환', '900 SKOR  ·  10% 절약', 'multi');
   140→
   141→    const back = this.add.text(200, 572, '← 돌아가기', {
   142→      fontSize: '14px', color: '#ffffff',
   143→      stroke: '#000000', strokeThickness: 3,
   144→    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
   145→    back.on('pointerover', () => back.setColor('#cccccc'));
   146→    back.on('pointerout',  () => back.setColor('#ffffff'));
   147→    back.on('pointerdown', () => this.scene.start('ModeSelectScene'));
   148→  }
   149→
   150→  private addPullButton(x: number, y: number, label: string, cost: string, type: 'single' | 'multi') {
   151→    const accentColor = type === 'single' ? 0xddaa00 : 0x7b2fff;
   152→    const accentHex   = type === 'single' ? '#ddaa00' : '#aa88ff';
   153→
   154→    const btn = this.add.rectangle(x, y, 310, 52, 0x000000, 0.72)
   155→      .setStrokeStyle(1.5, accentColor)
   156→      .setInteractive({ useHandCursor: true });
   157→
   158→    this.add.text(x, y - 9, label, {
   159→      fontSize: '20px', color: '#ffffff', fontStyle: 'bold',
   160→    }).setOrigin(0.5);
   161→    this.add.text(x, y + 13, cost, {
   162→      fontSize: '12px', color: accentHex,
   163→    }).setOrigin(0.5);
   164→
   165→    btn.on('pointerover', () => btn.setStrokeStyle(2.5, accentColor));
   166→    btn.on('pointerout',  () => btn.setStrokeStyle(1.5, accentColor));
   167→    btn.on('pointerdown', () => this.startPull(type));
   168→  }
   169→
   170→  // ═══════════════════════════════════════════════════
   171→  // PULL FLOW
   172→  // ═══════════════════════════════════════════════════
   173→
   174→  private async startPull(type: 'single' | 'multi') {
   175→    const cost = type === 'multi' ? 900 : 100;
   176→    if (this.skorBalance < 0) {
   177→      const errMsg = this.add.text(200, 370, '잔액 확인 중... 잠시 후 다시 시도하세요', {
   178→        fontSize: '13px', color: '#ffaa44',
   179→        stroke: '#000000', strokeThickness: 3,
   180→        backgroundColor: '#00000099',
   181→        padding: { x: 10, y: 5 },
   182→      }).setOrigin(0.5);
   183→      this.time.delayedCall(2000, () => { if (errMsg.active) errMsg.destroy(); });
   184→      return;
   185→    }
   186→    if (this.skorBalance < cost) {
   187→      const errMsg = this.add.text(200, 370, `SKOR 부족  (보유 ${Math.floor(this.skorBalance)} / 필요 ${cost})`, {
   188→        fontSize: '13px', color: '#ff5555',
   189→        stroke: '#000000', strokeThickness: 3,
   190→        backgroundColor: '#00000099',
   191→        padding: { x: 10, y: 5 },
   192→      }).setOrigin(0.5);
   193→      this.time.delayedCall(2200, () => { if (errMsg.active) errMsg.destroy(); });
   194→      return;
   195→    }
   196→
   197→    this.clearUI();
   198→
   199→    const count = type === 'multi' ? 10 : 1;
   200→
   201→    try {
   202→      // ① 영상(6초) + API 호출 병렬 실행 — 영상 보는 동안 응답 대기
   203→      const [result] = await Promise.all([
   204→        gachaPull(type),
   205→        this.playCommonVideo(),
   206→      ]);
   207→
   208→      if (!this.scene.isActive()) return;
   209→
   210→      this.pullResults = result.characters;
   211→      this.remainingSkor = result.remainingSkor;
   212→
   213→      // 신규 캐릭터 localStorage 동기화
   214→      result.characters.filter(c => c.isNew).forEach(c => addOwnedCharacter(c.id));
   215→
   216→      // ② 터미널 애니메이션 (UR이면 중반부터 빨간 에러 스타일로 전환)
   217→      const isUR = result.video === 'red'
   218→      this.skipTerminal = false;
   219→      this.clearUI();
   220→      this.add.rectangle(200, 300, 400, 600, 0x000000);
   221→      this.drawTerminalChrome(false); // 항상 초록으로 시작
   222→      this.addSkipButton(() => { this.skipTerminal = true; });
   223→      await this.runTerminalAnimation(count, isUR);
   224→      this.skipTerminal = false;
   225→
   226→      // ③ 캐릭터별 개인 영상 동적 로드 → 리빌
   227→      await this.loadCharVideos(result.characters.map(c => c.id));
   228→
   229→      this.revealIndex = 0;
   230→      this.showNextReveal();
   231→    } catch {
   232→      if (!this.scene.isActive()) return;
   233→      await this.typeLines([
   234→        '> CONNECTION ERROR',
   235→        '> Retrying in 3s...',
   236→      ], 30);
   237→      this.time.delayedCall(3000, () => this.buildLobby());
   238→    }
   239→  }
   240→
   241→  private async runTerminalAnimation(count: number, isUR = false): Promise<void> {
   242→    if (isUR) {
   243→      const red = '#ff3333';
   244→      // 초반: 정상처럼 초록으로 시작
   245→      await this.typeLines([
   246→        `> EXECUTE entity_summon(n=${count})`,
   247→        '> Establishing connection...',
   248→      ], 18);
   249→      await this.progressBar(400);
   250→      await this.typeLines([
   251→        '> CONN: OK  [sec-layer bypassed]',
   252→        '> Scanning entity pool...',
   253→      ], 16);
   254→      await this.progressBar(350);
   255→      // 이상 감지 시점부터 빨간색으로 전환
   256→      await this.typeLines([
   257→        '> [WARN] Anomaly detected',
   258→        '> [ERR]  Containment failure',
   259→      ], 18, red);
   260→      await this.progressBar(450, red);
   261→      await this.typeLines([
   262→        '> [CRIT] Unknown entity detected',
   263→        `> [!!!]  ${count} ENTR${count > 1 ? 'IES' : 'Y'} ESCAPED CONTAINMENT`,
   264→        '> EMERGENCY EXTRACTION . . .',
   265→      ], 20, red);
   266→    } else {
   267→      await this.typeLines([
   268→        `> EXECUTE entity_summon(n=${count})`,
   269→        '> Establishing connection...',
   270→      ], 18);
   271→      await this.progressBar(400);
   272→      await this.typeLines([
   273→        '> CONN: OK  [sec-layer bypassed]',
   274→        '> Scanning entity pool...',
   275→      ], 16);
   276→      await this.progressBar(350);
   277→      await this.typeLines([
   278→        '> Anomaly detected in sector 7',
   279→        '> Overriding...',
   280→      ], 18);
   281→      await this.progressBar(450);
   282→      await this.typeLines([
   283→        `> ${count} ENTR${count > 1 ? 'IES' : 'Y'} LOCKED`,
   284→        '> EXTRACTING . . .',
   285→      ], 20);
   286→    }
   287→    await this.sleep(200);
   288→  }
   289→
   290→  /** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
   291→  private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
   292→    vid.setDisplaySize(canvasW, canvasH); // 초기값
   293→
   294→    const applyContain = () => {
   295→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   296→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   297→      const nw = el?.videoWidth  || 0;
   298→      const nh = el?.videoHeight || 0;
   299→      if (nw > 0 && nh > 0) {
   300→        const scale = Math.max(canvasW / nw, canvasH / nh);
   301→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   302→      }
   303→    };
   304→
   305→    vid.once('play', applyContain);
   306→    this.time.delayedCall(100, applyContain);
   307→    this.time.delayedCall(500, applyContain);
   308→  }
   309→
   310→  private loadCharVideos(ids: string[]): Promise<void> {
   311→    const toLoad = ids.filter(
   312→      id => CHARS_WITH_VIDS.has(id) && !this.cache.video.exists(`vid_${id}`)
   313→    );
   314→    if (toLoad.length === 0) return Promise.resolve();
   315→
   316→    return new Promise(resolve => {
   317→      toLoad.forEach(id => this.load.video(`vid_${id}`, `assets/vids/${id}.mp4`));
   318→      this.load.once(Phaser.Loader.Events.COMPLETE, resolve);
   319→      this.load.once(Phaser.Loader.Events.FILE_LOAD_ERROR, resolve); // 실패해도 진행
   320→      this.load.start();
   321→    });
   322→  }
   323→
   324→  private playCommonVideo(_videoType?: string): Promise<void> {
   325→    return new Promise(resolve => {
   326→      const { width, height } = this.cameras.main;
   327→      this.clearUI();
   328→      this.add.rectangle(width / 2, height / 2, width, height, 0x000000);
   329→
   330→      const key = 'gacha';
   331→      if (!this.cache.video.exists(key)) { resolve(); return; }
   332→
   333→      const vid = this.add.video(width / 2, height / 2, key);
   334→      vid.play(false);
   335→      this.fitVideoToCanvas(vid, width, height);
   336→      vid.on('complete', () => { vid.destroy(); resolve(); });
   337→      this.time.delayedCall(12000, resolve); // 12초 failsafe
   338→    });
   339→  }
   340→
   341→  // ═══════════════════════════════════════════════════
   342→  // CHARACTER REVEAL
   343→  // ═══════════════════════════════════════════════════
   344→
   345→  private showNextReveal() {
   346→    if (this.revealIndex >= this.pullResults.length) {
   347→      this.showSummary();
   348→      return;
   349→    }
   350→
   351→    const pulled = this.pullResults[this.revealIndex];
   352→    const def = getCharacterDef(pulled.id);
   353→
   354→    const { width, height } = this.cameras.main;
   355→    this.clearUI();
   356→
   357→    const vidKey = `vid_${pulled.id}`;
   358→    if (this.cache.video.exists(vidKey)) {
   359→      const vid = this.add.video(width / 2, height / 2, vidKey);
   360→      vid.play(false);
   361→      this.fitVideoToCanvas(vid, width, height);
   362→
   363→      let proceeded = false;
   364→      const proceed = () => {
   365→        if (proceeded) return;
   366→        proceeded = true;
   367→        this.input.off('pointerdown', proceed);
   368→        if (vid.active) vid.destroy();
   369→        this.showRevealCard(pulled, def);
   370→      };
   371→
   372→      this.addSkipButton(() => {
   373→        if (proceeded) return;
   374→        proceeded = true;
   375→        this.input.off('pointerdown', proceed);
   376→        if (vid.active) vid.destroy();
   377→        // 10연차: 영상 스킵 시 남은 리빌 전체 건너뛰고 결과 화면으로
   378→        if (this.pullResults.length > 1) {
   379→          this.showSummary();
   380→        } else {
   381→          this.showRevealCard(pulled, def);
   382→        }
   383→      });
   384→      vid.on('complete', proceed);
   385→      this.time.delayedCall(10000, proceed); // failsafe
   386→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   387→    } else {
   388→      this.showRevealCard(pulled, def);
   389→    }
   390→  }
   391→
   392→  private showRevealCard(pulled: PulledCharacter, def: CharacterDef) {
   393→    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;
   394→
   395→    // ── 배경: 사이버 우주 이미지 + 등급 컬러 헤이즈 ──
   396→    if (this.textures.exists('gacha_background')) {
   397→      const bg = this.add.image(200, 300, 'gacha_background');
   398→      bg.setDisplaySize(400, 600);
   399→    } else {
   400→      this.add.rectangle(200, 300, 400, 600, 0x050510);
   401→    }
   402→    // 어두운 오버레이 (가독성 확보)
   403→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.5);
   404→    // 등급 컬러 헤이즈 (중앙 중심 방사)
   405→    this.add.circle(200, 260, 200, gColor, 0.08);
   406→    this.add.circle(200, 260, 120, gColor, 0.06);
   407→
   408→    // 배경 글로우 (캐릭터 뒤 빛)
   409→    const glow = this.add.circle(200, 255, 150, gColor, 0.0).setAlpha(0);
   410→    this.tweens.add({
   411→      targets: glow, alpha: 1,
   412→      scaleX: { from: 0.3, to: 1.3 }, scaleY: { from: 0.3, to: 1.3 },
   413→      duration: 600, ease: 'Back.easeOut',
   414→    });
   415→
   416→    // 캐릭터 이미지
   417→    const img = this.add.image(200, 240, def.imageKey).setAlpha(0);
   418→    img.setDisplaySize(130, 205);
   419→    this.tweens.add({
   420→      targets: img, alpha: 1, y: { from: 268, to: 240 },
   421→      duration: 500, ease: 'Back.easeOut', delay: 150,
   422→    });
   423→
   424→    // 등급 라벨
   425→    const gradeText = this.add.text(200, 388, pulled.grade, {
   426→      fontSize: '18px', color: def.gradeColor, fontStyle: 'bold',
   427→      stroke: '#000', strokeThickness: 4, fontFamily: 'monospace',
   428→    }).setOrigin(0.5).setAlpha(0);
   429→    this.tweens.add({ targets: gradeText, alpha: 1, duration: 300, delay: 400 });
   430→
   431→    // 캐릭터 이름
   432→    const nameText = this.add.text(200, 424, def.name, {
   433→      fontSize: '34px', color: '#ffffff', fontStyle: 'bold',
   434→      stroke: '#000000', strokeThickness: 6,
   435→    }).setOrigin(0.5).setAlpha(0);
   436→    this.tweens.add({
   437→      targets: nameText, alpha: 1, y: { from: 442, to: 424 },
   438→      duration: 400, ease: 'Back.easeOut', delay: 500,
   439→    });
   440→
   441→    // NEW! 배지
   442→    if (pulled.isNew) {
   443→      const badge = this.add.text(325, 145, ' NEW! ', {
   444→        fontSize: '15px', color: '#ffff00', fontStyle: 'bold',
   445→        backgroundColor: '#cc0000', stroke: '#000', strokeThickness: 2,
   446→      }).setOrigin(0.5).setAlpha(0).setScale(0);
   447→      this.tweens.add({
   448→        targets: badge, alpha: 1, scaleX: 1, scaleY: 1,
   449→        duration: 300, ease: 'Back.easeOut', delay: 650,
   450→      });
   451→    }
   452→
   453→    // 탭 안내
   454→    const isLast = this.revealIndex >= this.pullResults.length - 1;
   455→    const hint = isLast
   456→      ? 'TAP → RESULTS'
   457→      : `TAP → NEXT  (${this.revealIndex + 1}/${this.pullResults.length})`;
   458→    const tapHint = this.add.text(200, 562, hint, {
   459→      fontSize: '13px', color: '#555555', fontFamily: 'monospace',
   460→    }).setOrigin(0.5);
   461→    this.tweens.add({
   462→      targets: tapHint, alpha: { from: 0.3, to: 1 }, duration: 600, yoyo: true, repeat: -1,
   463→    });
   464→
   465→    // 10연차: 결과 화면으로 바로 건너뛰기 (영상 유무와 무관하게 항상 표시)
   466→    if (this.pullResults.length > 1) {
   467→      this.addSkipButton(() => {
   468→        this.tweens.killAll();
   469→        this.time.removeAllEvents();
   470→        this.input.off('pointerdown');
   471→        this.showSummary();
   472→      });
   473→    }
   474→
   475→    // 탭 진행 (700ms 디바운스)
   476→    this.time.delayedCall(700, () => {
   477→      if (!this.scene.isActive()) return;
   478→
   479→      let advanced = false;
   480→      const advance = () => {
   481→        if (advanced) return;
   482→        advanced = true;
   483→        this.input.off('pointerdown', advance);
   484→        this.tweens.killAll();
   485→        this.time.removeAllEvents();
   486→        this.revealIndex++;
   487→        this.showNextReveal();
   488→      };
   489→
   490→      this.input.on('pointerdown', advance);
   491→
   492→      // 10뽑기는 3.5초 자동 진행
   493→      if (this.pullResults.length > 1) {
   494→        this.time.delayedCall(3500, () => {
   495→          if (this.scene.isActive()) advance();
   496→        });
   497→      }
   498→    });
   499→  }
   500→
   501→  // ═══════════════════════════════════════════════════
   502→  // SUMMARY
   503→  // ═══════════════════════════════════════════════════
   504→
   505→  private showSummary() {
   506→    this.clearUI();
   507→    if (this.textures.exists('gacha_background')) {
   508→      this.add.image(200, 300, 'gacha_background').setDisplaySize(400, 600);
   509→    } else {
   510→      this.add.rectangle(200, 300, 400, 600, 0x060612);
   511→    }
   512→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.55);
   513→
   514→    this.add.text(200, 38, '[ EXTRACTION COMPLETE ]', {
   515→      fontSize: '17px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   516→    }).setOrigin(0.5);
   517→
   518→    // 결과 카드 그리드
   519→    const total = this.pullResults.length;
   520→    const cols = Math.min(total, 5);
   521→    const cardW = 64, cardH = 84, gapX = 8, gapY = 12;
   522→    const totalW = cols * cardW + (cols - 1) * gapX;
   523→    const startX = (400 - totalW) / 2 + cardW / 2;
   524→    const startY = total > 5 ? 130 : 175;
   525→
   526→    this.pullResults.forEach((pulled, i) => {
   527→      const def = getCharacterDef(pulled.id);
   528→      const col = i % 5;
   529→      const row = Math.floor(i / 5);
   530→      const x = startX + col * (cardW + gapX);
   531→      const y = startY + row * (cardH + gapY);
   532→      const gColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   533→
   534→      const bg  = this.add.rectangle(x, y, cardW, cardH, 0x111122).setStrokeStyle(1, gColorInt).setAlpha(0);
   535→      const img = this.add.image(x, y - 8, def.imageKey).setDisplaySize(cardW - 19, cardH - 22).setAlpha(0);
   536→      const nm  = this.add.text(x, y + cardH / 2 - 10, def.name, { fontSize: '9px', color: '#cccccc' }).setOrigin(0.5).setAlpha(0);
   537→
   538→      if (pulled.isNew) {
   539→        this.add.text(x + cardW / 2, y - cardH / 2 + 2, 'NEW', {
   540→          fontSize: '8px', color: '#ffff00', backgroundColor: '#aa0000', padding: { x: 2, y: 1 },
   541→        }).setOrigin(1, 0).setAlpha(0);
   542→      }
   543→
   544→      this.tweens.add({ targets: [bg, img, nm], alpha: 1, duration: 200, delay: i * 60 });
   545→    });
   546→
   547→    // 잔여 SKOR
   548→    const skorY = total > 5 ? 350 : 340;
   549→    this.add.text(200, skorY, `잔여 SKOR: ${Math.floor(this.remainingSkor)}`, {
   550→      fontSize: '14px', color: '#00ff41', fontFamily: 'monospace',
   551→    }).setOrigin(0.5);
   552→
   553→    // 한 번 더 / 메인으로 버튼
   554→    const againBtn = this.add.rectangle(200, 445, 260, 52, 0x080818)
   555→      .setStrokeStyle(1, 0x00ff41).setInteractive({ useHandCursor: true });
   556→    this.add.text(200, 445, '한 번 더', {
   557→      fontSize: '19px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   558→    }).setOrigin(0.5);
   559→    againBtn.on('pointerover', () => againBtn.setFillStyle(0x081808));
   560→    againBtn.on('pointerout',  () => againBtn.setFillStyle(0x080818));
   561→    againBtn.on('pointerdown', () => this.buildLobby());
   562→
   563→    const mainBtn = this.add.rectangle(200, 525, 260, 52, 0x1a1a1a)
   564→      .setStrokeStyle(1, 0x444444).setInteractive({ useHandCursor: true });
   565→    this.add.text(200, 525, '메인으로', {
   566→      fontSize: '19px', color: '#888888', fontStyle: 'bold', fontFamily: 'monospace',
   567→    }).setOrigin(0.5);
   568→    mainBtn.on('pointerover', () => mainBtn.setFillStyle(0x282828));
   569→    mainBtn.on('pointerout',  () => mainBtn.setFillStyle(0x1a1a1a));
   570→    mainBtn.on('pointerdown', () => this.scene.start('ModeSelectScene'));
   571→  }
   572→
   573→  // ═══════════════════════════════════════════════════
   574→  // 터미널 헬퍼
   575→  // ═══════════════════════════════════════════════════
   576→
   577→  private addSkipButton(onClick: () => void) {
   578→    this.add.rectangle(363, 28, 88, 30, 0x000000, 0.6)
   579→      .setInteractive()
   580→      .on('pointerdown', onClick);
   581→    const txt = this.add.text(363, 28, 'SKIP  ▶▶', {
   582→      fontSize: '12px', color: '#777777', fontFamily: 'monospace',
   583→    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
   584→    txt.on('pointerover', () => txt.setColor('#cccccc'));
   585→    txt.on('pointerout',  () => txt.setColor('#777777'));
   586→    txt.on('pointerdown', onClick);
   587→  }
   588→
   589→  private clearUI() {
   590→    this.tweens.killAll();
   591→    this.time.removeAllEvents();
   592→    this.input.off('pointerdown');
   593→    this.children.getAll().forEach(c => c.destroy());
   594→    this.terminalTexts = [];
   595→  }
   596→
   597→  private typeLines(lines: string[], delay = 40, color = '#00ff41'): Promise<void> {
   598→    return lines.reduce(
   599→      (p, line) => p.then(() => this.typeLine(line, delay, color)),
   600→      Promise.resolve()
   601→    );
   602→  }
   603→
   604→  private typeLine(text: string, charDelay = 40, color = '#00ff41'): Promise<void> {
   605→    return new Promise(resolve => {
   606→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   607→
   608→      // 최대 6줄 유지 (스크롤 효과)
   609→      if (this.terminalTexts.length >= 6) {
   610→        this.terminalTexts.shift()?.destroy();
   611→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   612→      }
   613→
   614→      const y = 276 + this.terminalTexts.length * 22;
   615→      const t = this.add.text(24, y, '', {
   616→        fontSize: '13px', color, fontFamily: 'monospace',
   617→      });
   618→      this.terminalTexts.push(t);
   619→
   620→      let i = 0;
   621→      const ev = this.time.addEvent({
   622→        delay: charDelay,
   623→        repeat: text.length,
   624→        callback: () => {
   625→          if (!this.scene.isActive() || this.skipTerminal) { ev.destroy(); resolve(); return; }
   626→          t.setText(text.substring(0, i + 1));
   627→          i++;
   628→          if (i > text.length) { ev.destroy(); resolve(); }
   629→        },
   630→      });
   631→    });
   632→  }
   633→
   634→  private progressBar(duration: number, color = '#00ff41'): Promise<void> {
   635→    return new Promise(resolve => {
   636→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   637→
   638→      if (this.terminalTexts.length >= 6) {
   639→        this.terminalTexts.shift()?.destroy();
   640→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   641→      }
   642→
   643→      const y = 276 + this.terminalTexts.length * 22;
   644→      const bar = this.add.text(24, y, '> [          ]  0%', {
   645→        fontSize: '13px', color, fontFamily: 'monospace',
   646→      });
   647→      this.terminalTexts.push(bar);
   648→
   649→      let step = 0;
   650→      const steps = 10;
   651→      const ev = this.time.addEvent({
   652→        delay: duration / steps,
   653→        repeat: steps - 1,
   654→        callback: () => {
   655→          step++;
   656→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   657→          if (this.skipTerminal || step >= steps) { ev.destroy(); resolve(); }
   658→        },
   659→      });
   660→    });
   661→  }
   662→
   663→  private sleep(ms: number): Promise<void> {
   664→    return new Promise(resolve => {
   665→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   666→      this.time.delayedCall(ms, resolve);
   667→    });
   668→  }
